import manifest from '../assets/images.json';

/**
 * Resolves an image key such as "stock/hero" or "projects/project-01" to the
 * hashed WebP variants generated by `npm run images`.
 */
const files = import.meta.glob('../assets/{projects,stock,team}/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
});

export function getImage(key) {
  const meta = manifest[key];
  if (!meta) {
    if (import.meta.env.DEV) console.warn(`[images] Unknown image "${key}". Did you run "npm run images"?`);
    return null;
  }
  const variants = meta.widths.map((w) => ({ w, url: files[`../assets/${key}-${w}.webp`] })).filter((v) => v.url);
  const fallback = variants.find((v) => v.w >= 1024) ?? variants[variants.length - 1];
  return {
    src: fallback.url,
    srcSet: variants.map((v) => `${v.url} ${v.w}w`).join(', '),
    largest: variants[variants.length - 1].url,
    width: meta.width,
    height: meta.height,
  };
}
